/*---
description: NFKC agrees with Node for every code point U+0E0000 through U+0EFFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [4041265605, 2445279685, 2007886277, 2760792517, 1259076037, 4127693253, 915239365, 559374789, 203233733, 1947787717, 1839757765, 2864159173, 2166948293, 298265029, 2327161285, 3556415941];
const blocks = ["NFKC U+0E0000-U+0E0FFF", "NFKC U+0E1000-U+0E1FFF", "NFKC U+0E2000-U+0E2FFF", "NFKC U+0E3000-U+0E3FFF", "NFKC U+0E4000-U+0E4FFF", "NFKC U+0E5000-U+0E5FFF", "NFKC U+0E6000-U+0E6FFF", "NFKC U+0E7000-U+0E7FFF", "NFKC U+0E8000-U+0E8FFF", "NFKC U+0E9000-U+0E9FFF", "NFKC U+0EA000-U+0EAFFF", "NFKC U+0EB000-U+0EBFFF", "NFKC U+0EC000-U+0ECFFF", "NFKC U+0ED000-U+0EDFFF", "NFKC U+0EE000-U+0EEFFF", "NFKC U+0EF000-U+0EFFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 917504 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFKC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
